48				// is available in the detail pane without being the summary.
49				c.fact("No route", fmt.Sprintf("%s — %v", ip, err))
50				unreachable = append(unreachable, ip)
51				continue
52			}
53			routed = append(routed, routedAddress{ip: ip, hop: hop})
54		}
55	
56		switch {
57		case len(routed) == 0:
58			// Every lookup failed. This is Unknown and not Fail on purpose: a
59			// lookup that could not answer is not the same as a machine with no
60			// route, and rendering the first as the second is the defect this
61			// codebase keeps finding (D20).
62			c.Summary = fmt.Sprintf("The local route to %s could not be determined", t.Host)
63			return []Check{c}
64		case len(unreachable) > 0:
65			c.Verdict = Warn
66			c.Reason = ReasonPartialRoute
67			c.Summary = fmt.Sprintf("%d of %d addresses have no local route",
68				len(unreachable), len(routed)+len(unreachable))
69		default:
70			c.Verdict = OK
71			c.Summary = routeSummary(routed)
72		}
73	
74		describeRoutes(&c, routed)
75		return []Check{c}
76	}
77	
78	// routedAddress pairs an address with the way out it was given.
79	type routedAddress struct {
80		ip  net.IP
81		hop RouteHop
82	}
83	
84	// routeSummary states the way out in one line.
85	//
86	// It names the interface rather than the gateway because the interface is what
87	// the user recognises — "ProtonVPN" answers the question, "10.2.0.1" needs a
88	// second lookup to mean anything.
89	func routeSummary(routed []routedAddress) string {
90		ifaces := make([]string, 0, len(routed))
91		seen := map[string]bool{}
92		for _, r := range routed {
93			if name := r.hop.Interface; name != "" && !seen[name] {
94				seen[name] = true
95				ifaces = append(ifaces, name)
96			}
97		}
98		switch len(ifaces) {
99		case 0:
100			return "Routed, but the outgoing interface has no name"
101		case 1:
102			return "Traffic leaves through " + ifaces[0]
103		default:
104			return "Traffic leaves through " + strings.Join(ifaces, " and ")
105		}
106	}
107	
108	// describeRoutes records one fact per address, plus the source and gateway of
109	// the first. The source address is what a firewall rule or an ACL sees, so it
110	// is worth a line of its own rather than being buried in a per-address string.
111	func describeRoutes(c *Check, routed []routedAddress) {
112		if len(routed) == 0 {
113			return
114		}
115		first := routed[0].hop
116		if first.Interface != "" {
117			c.fact("Interface", first.Interface)
118		}
119		if len(first.Source) > 0 {
120			c.fact("Source address", first.Source.String())
121		}
122		if len(first.Gateway) > 0 {
123			c.fact("Gateway", first.Gateway.String())
124		} else {
125			// "Directly connected" is an answer, and a blank line is not. A target
126			// on the local segment has no gateway, which is worth saying because it
127			// rules out every hop beyond it.
128			c.fact("Gateway", "directly connected")
129		}
130		for _, r := range routed {
131			c.fact("Route", fmt.Sprintf("%s via %s", r.ip, routeVia(r.hop)))
132		}
133	}
134	
135	// routeVia renders one hop for a per-address fact.
136	func routeVia(h RouteHop) string {
137		name := h.Interface
138		if name == "" {
139			name = "an unnamed interface"
140		}
141		if len(h.Gateway) > 0 {
142			return fmt.Sprintf("%s (gateway %s)", name, h.Gateway)
143		}
144		return name
145	}
146	
147	// targetAddresses is where this stage gets its addresses from.
148	//
149	// A literal target is its own answer. A name is not resolved a second time: the
150	// resolve stage already asked, and asking again would let the two disagree on a
151	// round-robin name — the route would then describe an address no other check in
152	// the run ever touched. The coupling is deliberate and pinned by
153	// TestTheRouteStageReadsWhatTheResolveStageWrote.
154	func targetAddresses(t Target, prior *Results) []net.IP {
155		if ip := net.ParseIP(strings.TrimSpace(t.Host)); ip != nil {
156			return []net.IP{ip}
157		}
158		if prior == nil {
159			return nil
160		}
161		c, ok := prior.Get(CheckResolve)
162		if !ok {
163			return nil
164		}
165		var out []net.IP
166		for _, f := range c.Facts {
167			if f.Key != "Address" {
168				continue
169			}
170			// The value is "<ip> (<class>)"; anything that is not an address is
171			// dropped by ParseIP rather than guarded against by shape.
172			if ip := net.ParseIP(strings.TrimSpace(strings.SplitN(f.Value, " ", 2)[0])); ip != nil {
173				out = append(out, ip)
174				if len(out) == maxRoutedAddresses {
175					break
176				}
177			}
178		}
179		return out
180	}
